package com.lqq.supportflow.eventing.application;
import com.lqq.supportflow.eventing.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DispatchOutboxService { private final OutboxPort outbox; private final OutboxDeliveryGateway delivery; public DispatchOutboxService(OutboxPort outbox,OutboxDeliveryGateway delivery){this.outbox=outbox;this.delivery=delivery;} @Transactional public int dispatch(int limit){int published=0;for(OutboxEvent event:outbox.pending(limit)){delivery.publish(event);outbox.markPublished(event.id());published++;}return published;}}
